const ee = require('@google/earthengine');
const privateKey = require('../auth_keys/test-project-473922-29f05d49bed7');

async function runAnalysis() {
  // 1. Geometry & Time Definitions
  const country = ee.FeatureCollection("USDOS/LSIB_SIMPLE/2017").filter(ee.Filter.eq('country_na', 'Denmark'));
  const geom = country.geometry();

  const targetDate1_2017 = ee.Date('2017-07-19');
  const targetDate2_2018 = ee.Date('2018-07-24');

  const dateWindowDays = 7; // Look +/- 7 days around the target date

  const startDate1 = targetDate1_2017.advance(-dateWindowDays, 'day');
  const endDate1 = targetDate1_2017.advance(dateWindowDays + 1, 'day'); // +1 to include the end day

  const startDate2 = targetDate2_2018.advance(-dateWindowDays, 'day');
  const endDate2 = targetDate2_2018.advance(dateWindowDays + 1, 'day'); // +1 to include the end day

  // Cloud masking function for Sentinel-2
  function maskS2clouds(image) {
    const qa = image.select('QA60');
    // Bits 10 and 11 are clouds and cirrus, respectively.
    const cloudBitMask = 1 << 10;
    const cirrusBitMask = 1 << 11;
    // Both flags should be set to zero, indicating clear conditions.
    const mask = qa.bitwiseAnd(cloudBitMask).eq(0)
      .and(qa.bitwiseAnd(cirrusBitMask).eq(0));
    return image.updateMask(mask).divide(10000); // Scale to reflectance
  }

  // Function to calculate NDVI
  function addNDVI(image) {
    const ndvi = image.normalizedDifference(['B8', 'B4']).rename('NDVI');
    return image.addBands(ndvi);
  }

  // 2. Data Acquisition & Check
  const s2Collection = ee.ImageCollection('COPERNICUS/S2_SR')
    .filterBounds(geom)
    .filter(ee.Filter.lt('CLOUDY_PIXEL_PERCENTAGE', 20)) // Filter out very cloudy images
    .map(maskS2clouds)
    .map(addNDVI);

  const col1_raw = s2Collection.filterDate(startDate1, endDate1);
  const col2_raw = s2Collection.filterDate(startDate2, endDate2);

  // Helper to get the image closest to the target date or a median
  function getRepresentativeImage(collection, targetDate, geom, periodName) {
    const size = collection.size().getInfo();
    if (size === 0) {
      console.log(`No images found for ${periodName} in the given date window.`);
      return { image: null, count: 0, cloud_percentage: null };
    }

    // Sort by difference to target date and take the first one
    const closestImage = collection.map(function(image) {
      const diff = ee.Number(image.get('system:time_start')).subtract(ee.Number(targetDate.millis())).abs();
      return image.set('date_diff', diff);
    }).sort('date_diff').first();

    const cloud_percentage = closestImage.get('CLOUDY_PIXEL_PERCENTAGE').getInfo();

    return { image: closestImage, count: size, cloud_percentage: cloud_percentage };
  }

  const result1 = getRepresentativeImage(col1_raw, targetDate1_2017, geom, '2017 period');
  const img1 = result1.image;
  const count1 = result1.count;
  const cloud_perc1 = result1.cloud_percentage;

  const result2 = getRepresentativeImage(col2_raw, targetDate2_2018, geom, '2018 period');
  const img2 = result2.image;
  const count2 = result2.count;
  const cloud_perc2 = result2.cloud_percentage;

  if (img1 === null || img2 === null) {
    console.log("C1: Empty Collection (No images found for one or both comparison points).");
    return;
  }

  // 3. Processing & Calculation
  const scale = 100; // Use a finer scale for more precise land cover (10m bands exist), but ensure maxPixels is sufficient
  const maxPixels = 1e10; // Increase maxPixels to handle large regions at fine scale

  // Calculate valid pixel count for image 1
  const pixelCount1 = img1.select('NDVI').reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: geom,
    scale: scale,
    maxPixels: maxPixels
  }).get('NDVI').getInfo();

  if (pixelCount1 === 0) {
    console.log(`2017 Images: ${count1} (Cloud %: ${cloud_perc1 !== null ? cloud_perc1.toFixed(1) : 'N/A'})`);
    console.log("C2: No Valid Pixels for 2017 after cloud masking/processing.");
    return;
  }

  // Calculate mean NDVI for image 1
  const meanNdvi1 = img1.select('NDVI').reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: geom,
    scale: scale,
    maxPixels: maxPixels
  }).get('NDVI').getInfo();

  // Calculate valid pixel count for image 2
  const pixelCount2 = img2.select('NDVI').reduceRegion({
    reducer: ee.Reducer.count(),
    geometry: geom,
    scale: scale,
    maxPixels: maxPixels
  }).get('NDVI').getInfo();

  if (pixelCount2 === 0) {
    console.log(`2017 Images: ${count1} (Cloud %: ${cloud_perc1 !== null ? cloud_perc1.toFixed(1) : 'N/A'}) (Val: ${pixelCount1})`);
    console.log(`2018 Images: ${count2} (Cloud %: ${cloud_perc2 !== null ? cloud_perc2.toFixed(1) : 'N/A'})`);
    console.log("C2: No Valid Pixels for 2018 after cloud masking/processing.");
    return;
  }

  // Calculate mean NDVI for image 2
  const meanNdvi2 = img2.select('NDVI').reduceRegion({
    reducer: ee.Reducer.mean(),
    geometry: geom,
    scale: scale,
    maxPixels: maxPixels
  }).get('NDVI').getInfo();

  // 4. Validation & Final Answer
  if (meanNdvi1 === null || meanNdvi2 === null || isNaN(meanNdvi1) || isNaN(meanNdvi2)) {
    console.log("C3: Calculation Failure (NDVI result is None or NaN).");
    return;
  }

  console.log(`2017 Images: ${count1} (Cloud %: ${cloud_perc1 !== null ? cloud_perc1.toFixed(1) : 'N/A'}) (Val Pixels: ${pixelCount1})`);
  console.log(`2017 Mean NDVI: ${meanNdvi1.toFixed(3)}`);
  console.log(`2018 Images: ${count2} (Cloud %: ${cloud_perc2 !== null ? cloud_perc2.toFixed(1) : 'N/A'}) (Val Pixels: ${pixelCount2})`);
  console.log(`2018 Mean NDVI: ${meanNdvi2.toFixed(3)}`);

  // Lower NDVI indicates "browner" appearance
  if (meanNdvi2 < meanNdvi1) {
    console.log("A");
  } else {
    console.log("B");
  }
}

async function initEE() {
  await new Promise((resolve, reject) => {
    ee.data.authenticateViaPrivateKey(privateKey, resolve, reject);
  });
  await new Promise((resolve, reject) => {
    ee.initialize(null, null, resolve, reject);
  });
  await runAnalysis();
}

initEE();
